import math
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

gelu_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor gelu_forward(torch::Tensor x);
"""

gelu_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <algorithm>

#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float fast_tanhf(float x) {
  // Hardware-accelerated tanh approximation (fast math intrinsic).
  float y;
  asm volatile("tanh.approx.f32 %0, %1;" : "=f"(y) : "f"(x));
  return y;
}
__device__ __forceinline__ float gelu_eltwise(float x) {
  // 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
  const float kAlpha = 0.7978845608028654f;
  const float kBeta  = 0.044715f;
  float x2 = x * x;
  float inner = kAlpha * fmaf(kBeta * x2, x, x);
  const float half_x = 0.5f * x;
  return fmaf(half_x, fast_tanhf(inner), half_x);
}

__global__ void gelu_cute_kernel(const float* __restrict__ X,
                                 float* __restrict__ Y,
                                 int64_t numel) {
  const int64_t nvec = numel >> 2;
  const float4* x4 = reinterpret_cast<const float4*>(X);
  float4* y4 = reinterpret_cast<float4*>(Y);
  Tensor mX4 = make_tensor(make_gmem_ptr(x4), make_shape(nvec));
  Tensor mY4 = make_tensor(make_gmem_ptr(y4), make_shape(nvec));
  const int64_t tid = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  const int64_t stride = (int64_t)gridDim.x * blockDim.x;
  constexpr int kUnroll = 4;
  for (int64_t base = tid; base < nvec; base += stride * kUnroll) {
    #pragma unroll
    for (int j = 0; j < kUnroll; ++j) {
      const int64_t i = base + (int64_t)j * stride;
      if (i < nvec) {
        float4 v = mX4(i);
        float4 r;
        r.x = gelu_eltwise(v.x);
        r.y = gelu_eltwise(v.y);
        r.z = gelu_eltwise(v.z);
        r.w = gelu_eltwise(v.w);
        mY4(i) = r;
      }
    }
  }
  Tensor mX = make_tensor(make_gmem_ptr(X), make_shape(numel));
  Tensor mY = make_tensor(make_gmem_ptr(Y), make_shape(numel));
  const int64_t tail_begin = nvec << 2;
  for (int64_t i = tail_begin + tid; i < numel; i += stride) {
    mY(i) = gelu_eltwise(mX(i));
  }
}

torch::Tensor gelu_forward(torch::Tensor x) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");

  auto x_c = x.contiguous();
  auto y = torch::empty_like(x_c);
  const int64_t numel = x_c.numel();
  if (numel == 0) {
    return y;
  }

  const float* x_ptr = x_c.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();

  constexpr int kThreads = 256;
  constexpr int kUnroll = 4;
  const int64_t nvec = numel >> 2;
  int64_t wanted = (nvec + (int64_t)kThreads * kUnroll - 1) / ((int64_t)kThreads * kUnroll);
  if (wanted == 0) wanted = 1;
  const int64_t capped = std::min<int64_t>(wanted, 1 << 20);
  dim3 block(kThreads);
  dim3 grid((unsigned)capped);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gelu_cute_kernel<<<grid, block, 0, stream>>>(x_ptr, y_ptr, numel);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "gelu_cute_kernel launch failed: ",
              cudaGetErrorString(err));
  return y;
}
"""

gelu_ext = load_inline(
    name="cute_gelu_inline",
    cpp_sources=gelu_cpp_decl,
    cuda_sources=gelu_cuda_src,
    functions=["gelu_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    GELU activation implemented by one fused custom CUDA/CUTE kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = gelu_ext

    def forward(self, x):
        if x.is_cuda:
            return self._ext.gelu_forward(x)
        # Keep CPU-input callers functional while still using the CUDA/CUTE kernel
        # for the actual computation.
        out = self._ext.gelu_forward(x.cuda())
        return out.to(x.device)

